// Component instances in a document: finding them, their provenance, inserting new ones, counting.
// An instance is any node with `data-ds` (a part root generated by `generate`); nodes inside it that were generated with it carry only `data-slot`.

import type { DocumentOps, OcelotDocument } from '../../model/document';
import type { Scheme } from '../model';
import { DS_ATTR, DS_PROPS_ATTR, generate, resolveProps, type GenerateRecord } from './generate';
import type { ComponentSet } from './set';
import type { AncestorPart, ComponentRequest, InstanceCount } from './types';

export const SCHEME_ATTR = 'data-ds-scheme';
/** On the root layers of an inserted block: the shadcn block they come from (`login-02`). Provenance only; nothing links back. */
export const BLOCK_ATTR = 'data-ds-block';

/** The shadcn blocks the layers of an artboard were inserted from, in document order and without repeats. */
export function blocksIn(doc: OcelotDocument, artboardId: string): string[] {
  const out: string[] = [];
  const visit = (id: string) => {
    const n = doc.get(id);
    if (!n) return;
    const b = n.attrs[BLOCK_ATTR];
    if (b && !out.includes(b)) out.push(b);
    for (const c of n.children) visit(c);
  };
  visit(artboardId);
  return out;
}

/** The color scheme of the artboard that holds `nodeId` (`data-ds-scheme` on its root; default: the record's, else light). */
export function schemeOf(doc: OcelotDocument, nodeId: string): Scheme {
  const ab = doc.artboardOf(nodeId);
  return ab ? doc.artboardScheme(ab) : 'light';
}

/** The explicit props stored on an instance (`data-ds-props`); an unreadable value is treated as no props. */
export function readProps(attrs: Readonly<Record<string, string>>): Record<string, string | boolean> {
  const raw = attrs[DS_PROPS_ATTR];
  if (!raw) return {};
  try {
    const v: unknown = JSON.parse(raw);
    if (typeof v !== 'object' || v === null || Array.isArray(v)) return {};
    const out: Record<string, string | boolean> = {};
    for (const [k, x] of Object.entries(v)) if (typeof x === 'string' || typeof x === 'boolean') out[k] = x;
    return out;
  } catch {
    return {};
  }
}

const propValues = (props: Record<string, string | boolean>): Record<string, string> =>
  Object.fromEntries(Object.entries(props).filter((e): e is [string, string] => typeof e[1] === 'string'));

/**
 * The instances above `nodeId` (root first), for `inherit` props and context flags. `component` is the catalog component of the part when `set`
 * knows it. `props` are the part's RESOLVED props, as `generate` hands them to its children (a field with no stored `orientation` is vertical):
 * a label inside it is styled by that orientation, and the export must see the same one.
 */
export function ancestorParts(doc: OcelotDocument, nodeId: string, set: ComponentSet): AncestorPart[] {
  const chain: Array<{ part: string; explicit: Record<string, string | boolean> }> = [];
  let cur = doc.get(nodeId)?.parent ?? null;
  while (cur) {
    const n = doc.get(cur);
    if (!n) break;
    const part = n.attrs[DS_ATTR];
    if (part) chain.unshift({ part, explicit: readProps(n.attrs) });
    cur = n.parent;
  }
  const out: AncestorPart[] = [];
  for (const { part, explicit } of chain) {
    const tpl = set.part(part);
    let props = propValues(explicit);
    try {
      if (tpl) props = resolveProps(tpl, explicit, out).values;
    } catch {
      // a stored prop this snapshot no longer knows: keep what is stored
    }
    out.push({ part, component: tpl?.component ?? part, props });
  }
  return out;
}

/** Every instance (node with `data-ds`) in the subtrees of `roots`, in document order. */
export function findInstances(doc: OcelotDocument, roots: readonly string[]): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  const walk = (id: string) => {
    if (seen.has(id)) return;
    seen.add(id);
    const n = doc.get(id);
    if (!n) return;
    if (n.attrs[DS_ATTR]) out.push(id);
    for (const c of n.children) walk(c);
  };
  roots.forEach(walk);
  return out;
}

/** Instances in the document (top-level roots, all parts, per component and per artboard). */
export function countInstances(doc: OcelotDocument, artboardIds?: readonly string[]): InstanceCount {
  const count: InstanceCount = { total: 0, parts: 0, byComponent: {}, byArtboard: {} };
  for (const ab of artboardIds ?? doc.artboardIds()) {
    const visit = (id: string, inside: boolean) => {
      const n = doc.get(id);
      if (!n) return;
      const part = n.attrs[DS_ATTR];
      if (part) {
        count.parts++;
        count.byComponent[part] = (count.byComponent[part] ?? 0) + 1;
        count.byArtboard[ab] = (count.byArtboard[ab] ?? 0) + 1;
        if (!inside) count.total++;
      }
      for (const c of n.children) visit(c, inside || Boolean(part));
    };
    visit(ab, false);
  }
  return count;
}

export interface InsertComponentsInput {
  parentId: string;
  items: readonly ComponentRequest[];
  index?: number;
}

/**
 * Generates `items` for the artboard's scheme and inserts them into `parentId` (an artboard or frame) as one transaction.
 * Nothing is written when any item fails to generate (a ComponentError names what to change).
 */
export function insertComponents(
  doc: OcelotDocument,
  ops: DocumentOps,
  set: ComponentSet,
  record: GenerateRecord,
  input: InsertComponentsInput,
): { ids: string[]; warnings: string[] } {
  const warnings: string[] = [];
  const scheme = schemeOf(doc, input.parentId);
  const ancestors = ancestorParts(doc, input.parentId, set);
  // The parent itself may be an instance (a card): its props feed `inherit`.
  const parent = doc.get(input.parentId);
  if (parent?.attrs[DS_ATTR]) ancestors.push({ part: parent.attrs[DS_ATTR]!, component: set.part(parent.attrs[DS_ATTR]!)?.component ?? parent.attrs[DS_ATTR]!, props: propValues(readProps(parent.attrs)) });
  const specs = input.items.map((req) => generate(set, record, req, { scheme, ancestors, warn: (m) => warnings.push(m) }));
  const ids = ops.insertNodes(input.parentId, specs, input.index);
  return { ids, warnings };
}
